void buildMinHeap(int arr[], int size) {
    // Helper function to heapify a subtree rooted at index i
    auto heapify = [arr, size](int i) mutable {
        int smallest = i;
        int left = 2 * i + 1;
        int right = 2 * i + 2;

        if (left < size && arr[left] < arr[smallest])
            smallest = left;

        if (right < size && arr[right] < arr[smallest])
            smallest = right;

        if (smallest != i) {
            std::swap(arr[i], arr[smallest]);
            // Recursively heapify the affected subtree
            int new_i = smallest;
            int new_smallest = new_i;
            int new_left = 2 * new_i + 1;
            int new_right = 2 * new_i + 2;

            if (new_left < size && arr[new_left] < arr[new_smallest])
                new_smallest = new_left;

            if (new_right < size && arr[new_right] < arr[new_smallest])
                new_smallest = new_right;

            if (new_smallest != new_i) {
                std::swap(arr[new_i], arr[new_smallest]);
            }
        }
    };

    // Build min heap by heapifying from bottom up
    for (int i = size / 2 - 1; i >= 0; i--) {
        int current = i;
        while (true) {
            int smallest = current;
            int left = 2 * current + 1;
            int right = 2 * current + 2;

            if (left < size && arr[left] < arr[smallest])
                smallest = left;

            if (right < size && arr[right] < arr[smallest])
                smallest = right;

            if (smallest == current)
                break;

            std::swap(arr[current], arr[smallest]);
            current = smallest;
        }
    }
}

