void buildMinHeap(int arr[], int size) {
    // Helper lambda to heapify a subtree rooted at index i
    auto heapify = [](int arr[], int size, int i) {
        int smallest = i;
        int left = 2 * i + 1;
        int right = 2 * i + 2;

        if (left < size && arr[left] < arr[smallest])
            smallest = left;

        if (right < size && arr[right] < arr[smallest])
            smallest = right;

        if (smallest != i) {
            std::swap(arr[i], arr[smallest]);
            heapify(arr, size, smallest);
        }
    };

    // Build min heap by heapifying from bottom up
    for (int i = size / 2 - 1; i >= 0; i--) {
        int current = i;
        while (true) {
            int smallest = current;
            int left = 2 * current + 1;
            int right = 2 * current + 2;

            if (left < size && arr[left] < arr[smallest])
                smallest = left;

            if (right < size && arr[right] < arr[smallest])
                smallest = right;

            if (smallest == current)
                break;

            std::swap(arr[current], arr[smallest]);
            current = smallest;
        }
    }
}

